def sift_down(lst, i, n):
    while True:
        left = 2 * i + 1
        right = 2 * i + 2
        smallest = i
        if left < n and lst[left] < lst[smallest]:
            smallest = left
        if right < n and lst[right] < lst[smallest]:
            smallest = right
        if smallest != i:
            lst[i], lst[smallest] = lst[smallest], lst[i]
            i = smallest
        else:
            break
