def min_jumps(arr, n):
    if n <= 1:
        return 0
    if arr[0] == 0:
        return -1

    # dp[i] will store the minimum jumps to reach index i
    dp = [float('inf')] * n
    dp[0] = 0

    for i in range(1, n):
        for j in range(i - arr[i - 1], i + 1):
            if 0 <= j < n:
                dp[i] = min(dp[i], dp[j - 1] + 1)

    return dp[n - 1]
```

