def min_Swaps(s1, s2):
    # Count the number of mismatched positions
    mismatches = 0
    for i in range(len(s1)):
        if s1[i] != s2[i]:
            mismatches += 1

    # If no mismatches, no swaps are needed
    if mismatches == 0:
        return 0

    # Find the first mismatched position
    first_mismatch = -1
    for i in range(len(s1)):
        if s1[i] != s2[i]:
            first_mismatch = i
            break

    # Count how many positions need to be swapped
    # Each swap can fix at most 2 mismatches
    return mismatches // 2
```

