        return 0
    s1 = list(s1)
    s2 = list(s2)
    count = 0
    visited = [False] * len(s1)
    for i in range(len(s1)):
        if s1[i] != s2[i]:
            count += 1
            if visited[i]:
                continue
            visited[i] = True
            j = i
            while j < len(s1) and s1[j] != s2[j]:
