def check_min_heap(arr, index):
    n = len(arr)
    if n == 0:
        return True

    # Check if the current node is smaller than its children
    left_child = 2 * index + 1
    right_child = 2 * index + 2

    if left_child < n:
        if arr[index] > arr[left_child]:
            return False

    if right_child < n:
        if arr[index] > arr[right_child]:
            return False

    # Recursively check the subtrees
    if index < n:
        return check_min_heap(arr, left_child) and check_min_heap(arr, right_child)

    return True
