def find_triplet_array(arr, target, k):
    arr.sort()
    n = len(arr)
    for i in range(n - k + 1):
        left = i + 1
        right = n - 1
        while left < right:
            current_sum = arr[i] + arr[left] + arr[right]
            if current_sum == target:
                return (arr[i], arr[left], arr[right])
            elif current_sum < target:
                left += 1
            else:
                right -= 1
    return None
```

