    if r < g and g < b:
        h = (b - r) / (b - r - g + b)
        if b >= g:
            s = (r - min(g, b)) / (1 - min(g, b))
        else:
            s = (r - min(g, b)) / (1 - min(g, b))
        v = max(r, g, b)
        if v == 0:
            h = 0
        return (h * 360, s * 100, v * 100)
    elif r < b and g < b:
        h = (r - b) / (r - b - g + b)
        if r >= g:
            s = (b - min(r, g)) / (1 - min(r, g))
        else:
