import heapq

def cheap_items(items, n):
    if n <= 0 or not items:
        return []

    # Use a min-heap to keep track of the n cheapest items
    # We store (price, index) to handle duplicate prices correctly
    heap = []

    for i, item in enumerate(items):
        price = item['price']
        if len(heap) < n:
            heapq.heappush(heap, (price, i))
        else:
            # If current item is cheaper than the most expensive in the heap
            if price < heap[0][0]:
                heapq.heappop(heap)
                heapq.heappush(heap, (price, i))

    # Extract results and remove indices
    result = []
    for price, idx in heap:
        result.append(items[idx])

    return result
