def min_Swaps(s1, s2):
    # Count the number of mismatched positions
    mismatches = 0
    for i in range(len(s1)):
        if s1[i] != s2[i]:
            mismatches += 1

    # If there are no mismatches, no swaps are needed
    if mismatches == 0:
        return 0

    # Find the first position where s1[i] != s2[i]
    # and determine the pattern of mismatches
    # We need to find cycles in the permutation
    n = len(s1)
    visited = [False] * n
    swaps = 0

    for i in range(n):
        if s1[i] != s2[i] and not visited[i]:
            # Start a new cycle
            cycle_len = 0
            curr = i
            while not visited[curr]:
                visited[curr] = True
                cycle_len += 1
                # Move to the next position in the cycle
                # If s1[curr] is '0', we need it to be '1', so we look for '1' in s2
                # If s1[curr] is '1', we need it to be '0', so we look for '0' in s2
                if s1[curr] == '0':
                    # Find the next '1' in s2 that is currently '0' in s1
                    for j in range(curr + 1, n):
                        if s1[j] == '0' and s2[j] == '1':
                            curr = j
                            break
                else:
                    # s1[curr] is '1', find the next '0' in s2 that is currently '1' in s1
                    for j in range(curr + 1, n):
                        if s1[j] == '1' and s2[j] == '0':
                            curr = j
                            break
            # Minimum swaps for this cycle is cycle_len - 1
            swaps += cycle_len - 1

    return swaps
```

