```python
def rgb_to_hsv(r, g, b):
    r, g, b = r / 255.0, g / 255.0, b / 255.0
    max_val = max(r, g, b)
    min_val = min(r, g, b)
    delta = max_val - min_val

    if max_val == 0:
        return (0, 0.0, 0.0)

    if max_val == r:
        h = (g - b) / delta
    elif max_val == g:
        h = (b - r) / delta + 2
    else:
        h = (r - g) / delta + 4

    h = h * 60
    if h < 0:
        h += 360

    sat = delta / max_val if max_val != 0 else 0
    val = max_val

    return (int(h), sat, val * 100)
```

