def min_difference(tuples):
    min_diff = float('inf')
    for i in range(len(tuples)):
        for j in range(i + 1, len(tuples)):
            for a, b in [(tuples[i][0], tuples[i][1]), (tuples[j][0], tuples[j][1])]:
                for c, d in [(tuples[i][0], tuples[i][1]), (tuples[j][0], tuples[j][1])]:
                    if (a, b) != (c, d):
                        diff = abs(a - c) + abs(b - d)
                        min_diff = min(min_diff, diff)
    return min_diff
```

