        return None
    if a > b:
        return None
    if a >= n or b >= m:
        return None
    if a + n > b or a + m > b:
        return None
    if a + n <= b and a + m <= b:
        return (a, a + n - 1, a + m - 1, a + m + n - 2)
    return None
