```python
def rgb_to_hsv(r, g, b):
    r, g, b = r / 255.0, g / 255.0, b / 255.0
    max_val = max(r, g, b)
    min_val = min(r, g, b)
    delta = max_val - min_val

    if max_val == 0:
        h = 0
    else:
        if r == max_val:
            h = 2 * ((g - b) / delta) % 1.0
        elif g == max_val:
            h = 2 * ((b - r) / delta) % 1.0 + 0.5
        else:
            h = 2 * ((r - g) / delta) % 1.0 + 0.5

    h = h * 360
    if max_val == 0:
        s = 0
    else:
        s = delta / max_val
    v = max_val

    return (h, s * 100, v * 100)
```

